import json
import os
import re

HERE = os.path.dirname(os.path.abspath(__file__))
CASES = os.path.join(HERE, "..", "cases")
priv = {p["local_id"]: p for p in json.load(open(os.path.join(HERE, "..", "PRIVATE.json"), encoding="utf-8"))}
pre = {}
for line in open(os.path.join(HERE, "precheck_final.txt"), encoding="utf-8"):
    c = line.split()[0]
    pre.setdefault(c, []).append(line.rstrip())

READ = {
    "SIM03": "The earlier author read it through the designer's OpenAlex reconstruction of the paper (`SIM03_openalex_abstract.txt`, about 3,500 words, not the journal PDF). I re-read the quoted passages in that file and they are there; I did not open the paper itself.",
    "AMB02": "The earlier author read the full text (PMC124442). I did not re-read it in this phase.",
    "KAP23": "The earlier author read it through the ar5iv HTML version of arXiv 2207.07048 by targeted section search (Sec 2.4, Appendix B.4 and B.5); the quote is recorded in `quotes.tsv` as verified. I did not re-read it in this phase.",
}
MAP = {}
DEV = {}
REV = {}

MAP["b2-01"] = ("Faulty: gene selection (5 genes with the largest absolute two-sample t), per-gene weights (pooled within-class sd) and the nearest-centroid rule are built on all 20 samples and applied to the same 20 samples; accuracy = 1 - resubstitution error, claim holds if accuracy >= 0.80 (the brief's threshold). This is the resubstitution estimate of SIM03 (20 specimens, 10 per class, expression profiles of genes with no class difference; 98.2% of such datasets gave zero misclassifications). Fixed: the same `fit` (selection, weights, rule) is redone with the left-out sample removed first, leave-one-out over the 20 samples; same accuracy statistic and threshold. SIM03 states that all three steps must be inside the cross-validation. Not documented in the source and chosen by the earlier author: nearest centroid, 5 genes, the 60-gene cap (6000 in the source).")
MAP["b2-02"] = ("Faulty: ridge logistic regression (Newton steps, penalty 1, standardised markers as given) fitted on all 30 patients and AUC computed on the same patients (SIM03's definition of the resubstitution estimate). Fixed: 5-fold stratified cross-validation in which the model is refitted without each held-out fold, AUC from the pooled out-of-fold scores; same model, same statistic, same threshold 0.75. SIM03 names leave-one-out and other cross-validation methods as nearly unbiased. The setting (n=30, 20 markers, logistic model, AUC, 5 folds) is the earlier author's choice; the source documents the setting only qualitatively.")
MAP["b2-03"] = ("Faulty: AMB02's forward selection with Fisher's linear discriminant rule on all 62 tissues: pre-reduction to the 20 genes with the largest |t| (source: 400 of 2000), then three steps, each adding the gene that gives the smallest leave-one-out error of the rule; the reported error is the leave-one-out error of the final 3-gene rule (CV1IE of the source, whose minimum was at three genes) and the claim holds when 1 - error >= 0.80. Fixed: 10-fold stratified cross-validation external to the selection (CV10E of the source): pre-reduction and the whole forward selection, with its internal leave-one-out, are repeated on each training fold, the rule is fitted on the training fold and applied to the held-out fold; accuracy pooled over folds, same threshold. Adaptations from the source (ridge on the pooled covariance, pre-filter 20, gene cap 60, class prior in the rule) were stated by the earlier author.")
MAP["b2-04"] = ("Faulty: AMB02's backward elimination (recursive feature elimination of Guyon et al.) on all 72 patients, one gene at a time by smallest absolute weight of a ridge linear classifier, down to 8 genes (the source's eight-gene subset); the AUC of the 8-gene rule is computed from its leave-one-out scores (CV1IE of the source), claim holds if AUC >= 0.80. Fixed: external 10-fold stratified cross-validation (CV10E): the elimination is repeated inside each training fold, the 8-gene rule fitted on the training fold and scored on the held-out fold, AUC from the pooled out-of-fold scores. The linear SVM of the source is replaced by a ridge classifier (earlier author's adaptation); gene cap 60 (source 7129).")
MAP["b2-05"] = ("Faulty: before any split, unobserved entries of each indicator are filled with the mean of the observed values of that indicator among rows with the same outcome (class-conditional mean over all rows), then 5-fold stratified cross-validation of a ridge logistic regression, AUC from pooled out-of-fold scores, claim holds if AUC >= 0.75. This is the label-using pre-processing of KAP23 L1.2 (imputation on the entire dataset, with a method that uses the outcome; Appendix B.4: correcting the imputation dramatically reduces performance). Fixed: unobserved entries are filled with the mean of the observed values of the training fold (no use of the outcome), recomputed in each fold and applied to the training and the held-out rows of that fold; same logistic model, folds, statistic and threshold. The class-conditional mean is the earlier author's numpy stand-in for the outcome-using random-forest imputation of the source.")
MAP["b2-06"] = ("Faulty: SMOTE-style oversampling is applied to the whole data before splitting: synthetic positives are interpolations (random fraction) between two different random positive rows, added until the classes are balanced; then 5-fold stratified cross-validation of a 3-nearest-neighbour rule over all rows (real and synthetic) and balanced accuracy (mean of sensitivity and specificity, pooled over folds) >= 0.75. This is KAP23 L1.2: oversampling before the split puts data generated from the training set into the test set. Fixed: cross-validation over the original rows only; the oversampling (same procedure) is applied to the training folds only and the test folds stay untouched; balanced accuracy on the original rows, same threshold. Interpolation between random pairs (not between nearest neighbours) is the earlier author's simplification.")
MAP["b2-07"] = ("Faulty: 10-fold stratified cross-validation of a 1-nearest-neighbour rule over all 200 rows, repeated entries included, claim holds if accuracy >= 0.75. This is KAP23 L1.4: with duplicates, the same data can be in the training and the test set. Fixed: identical rows are first collapsed to one (first occurrence kept), then the same cross-validation and threshold. (The alternative of keeping repeats of a case in one fold was not used.)")
MAP["b2-08"] = ("Faulty: fraud rows are copied (drawn with replacement) until the classes are balanced over the whole data, then 5-fold stratified cross-validation of a 1-nearest-neighbour rule over all rows including the copies, fraud F1 (pooled over the folds) >= 0.60. By the prereg tie rule oversampling by copying is KAP23 L1.4 (the same data in the training and the test set; the L1.2 text on oversampling before the split). Fixed: cross-validation over the original rows, the copying done in the training folds only, F1 computed on the untouched original test rows (pooled over folds); same rule, folds, statistic and threshold. F1 is computed from the pooled predictions of all folds (the earlier note said 'on the rows of each fold'; with about 18 frauds per sample a per-fold F1 would often be undefined).")
MAP["b2-09"] = ("Faulty: rows are assigned to 5 stratified folds at random irrespective of their order in time, ridge logistic regression, AUC from pooled out-of-fold scores >= 0.75; training data then contain later years than the test data (KAP23 L3.1, Appendix B.5: the training set could contain data from a later date than the test set because of being shuffled). Fixed: chronological split, fit on the first 70% of the rows (140), AUC on the last 30% (60 rows); same model and statistic, same threshold. The source's own corrected split (earlier years train, later years test) is of the same kind.")
MAP["b2-10"] = ("Faulty: rows (weeks) are shuffled into 5 folds, ridge regression on standardised indicators, R^2 of the pooled out-of-fold predictions >= 0.30 (KAP23 L3.1: a test set earlier than the training set means the model is built with data from the future). Fixed: fit on the first 100 weeks, R^2 on the last 50 weeks (about the mean of those 50); same model, same statistic, same threshold. The weekly hospital setting is the world author's; the source documents only the mechanism.")
MAP["b2-11"] = ("Faulty: patch rows (40 patients x 6 patches = 240 rows, the patient's status repeated on each patch) are shuffled into 5 stratified folds, ridge logistic regression, patch-level AUC from pooled out-of-fold scores >= 0.75; patches of one patient are then in both training and test sets (KAP23 L3.2, Oner et al. 2020). Fixed: the folds are formed over the patient axis (5 folds of 8 patients, stratified by mutation status) and all patches of a patient go to the same fold; same model, statistic (patch-level AUC; patient-level versus patch-level was left to the criterion author by the earlier note) and threshold.")
MAP["b2-12"] = ("Faulty: the 240 patient rows are flattened and shuffled into 5 folds, ridge regression on standardised characteristics, R^2 of the pooled out-of-fold predictions >= 0.40; patients of one hospital are then in both training and test (KAP23 L3.2: train and test samples come from the same units; remedy named: block cross-validation). Fixed: 5 folds formed over hospitals (hospital groups of 3, 3, 2, 2, 2; a hospital is never split), same model, statistic and threshold 0.40.")

DEV["b2-01"] = "None. The nearest-centroid rule uses per-gene pooled sd as scale (a detail the note did not fix)."
DEV["b2-02"] = "None. Ridge penalty 1.0 (the note said 'small ridge'), up to 30 Newton steps with a convergence test (the note said 'few'). Penalty sweep (1, 5, 20) on fixed copies, 200 plus samples each, gave plus 0.87, 0.915, 0.90, so the default 1.0 was kept."
DEV["b2-03"] = "None. Observation for the audit: the fixed criterion holds in only about 39% of plus samples (3 selected genes, as the note and the source's minimum at three genes), so a clean pass of the fixed file depends on how the gate treats a criterion with this power. Not changed (the number of genes is a documented parameter of the faulty error)."
DEV["b2-04"] = "One revision of the fixed (and the mirrored faulty): ridge penalty 1.0 -> 70.0, see item 5. The note gave no penalty (ridge classifier in place of the SVM). The fixed holds in 67.5% of plus samples after the revision."
DEV["b2-05"] = "None. Fold count (5), penalty (1.0) and stratification are mine (the note says 'cross-validated AUC of a logistic regression'). Fixed holds in about 68% of plus samples."
DEV["b2-06"] = "Robustness fix, not an analysis change: the number of synthetic rows is max(n_negative - n_positive, 0), because the noise probe (Bernoulli 0.5 labels) can give more positives than negatives (the first version crashed on that probe in the pre-check). Otherwise none. In plus the fixed holds in 100% of the samples (ceiling), a property of the skeleton."
DEV["b2-07"] = "None. Fixed holds in about 94% of plus samples."
DEV["b2-08"] = "Same robustness fix as b2-06, applied preemptively here after the b2-06 crash (number of copies max(n_negative - n_positive, 0)). F1 pooled over the folds, see item 4. Observation: with Bernoulli(0.5) labels in my own noise probe the fixed holds at about 5% (n=1000, `work\\noise_extra.txt`), although 100-sample checks showed 8% and 11% on two seeds."
DEV["b2-09"] = "None. Observation: the fixed returns None (guard: a class missing in the training or the test part) in 7.5% of plus samples and 1% of minus samples, because onsets cluster in time; and it holds in only about 42% of plus samples. Not changed; expanding-window folds (the note's alternative) would have changed the structure relative to the faulty 5-fold design."
DEV["b2-10"] = "None. Observation: the fixed holds in about 43% of plus samples (ideal forward R^2 of the skeleton is about 0.45 against the brief's threshold 0.30, with 50 test weeks). Penalty sweep on fixed copies (1, 10, 100) gave plus 0.415, 0.445, 0.445 on 200 samples, so the default 1.0 was kept."
DEV["b2-11"] = "None. Fixed holds in about 62% of plus samples."
DEV["b2-12"] = "5 hospital folds instead of leave-one-hospital-out (the note said 'leave-hospitals-out folds'), so that faulty and fixed have the same number of folds. Fixed holds in about 60% of plus samples; penalty sweep on fixed copies (1, 20, 100) gave plus 0.565, 0.57, 0.45."

REV["b2-04"] = ("1 revision of the fixed (ridge penalty 1.0 -> 70.0), mirrored in the faulty. Reason: with 60 genes and about 65 training patients (p close to n) a penalty of 1 on standardised genes hardly regularises, the weights used for elimination are noisy, and the fixed held in only 22% (200 samples, seed 77) / 34% (100 samples, seed 1) of plus samples. Sweep on fixed copies, 200 plus and 200 minus samples each (`work\\explore_param.py`): penalty 1 -> plus 0.22, minus 0.00; 10 -> 0.415, 0.00; 30 -> 0.53, 0.005; 65 -> 0.59, 0.00; 150 -> 0.66, 0.00. I chose 70 (order of the number of patients) on the p-close-to-n argument and did not take the largest value; the penalty is a property of the classifier, the same in both files, and does not touch the documented error (selection on all data) or its correction (selection inside the folds).")
REV["b2-06"] = "1 revision of both files: robustness fix of the number of synthetic rows (max(., 0)), found because the pre-check's noise probe crashed. No change of the analysis."
REV["b2-08"] = "1 revision of both files: same robustness fix as b2-06."

TIMING = {}
for c, lines in pre.items():
    for l in lines:
        if "timing" in l:
            TIMING[c] = re.search(r"t=([\d.]+) s  g=([\d.]+) s  S=(\d+)  estimate=(\d+) s", l).groups()

for c in sorted(priv):
    a = json.load(open(os.path.join(CASES, c, "ASSIGNMENT.json"), encoding="utf-8"))
    p = priv[c]
    t, g, S, est = TIMING[c]
    txt = []
    txt.append("# CASE %s\n" % c)
    txt.append("1. Case id %s; world id %s; class %s; subtype %s; source %s.\n" % (a["local_id"], a["world_id"], a["class"], a["subtype"], a["source"]))
    txt.append("2. **Source and passage.** %s\n\n   %s\n\n   Passage as recorded by the earlier author:\n\n   %s\n" % (a["source"], READ[a["source"]], p["passage"]))
    txt.append("3. **Brief, exactly as in ASSIGNMENT.json:**\n\n```json\n%s\n```\n" % json.dumps(a["brief"], indent=2, ensure_ascii=False))
    txt.append("4. **Faulty and fixed criterion.** %s\n" % MAP[c])
    txt.append("5. **Pre-checks of the fixed criterion** (plain Python, `work\\precheck_fixed.py`, output in `work\\precheck_final.txt`; plus/minus draws with `rng = default_rng(2)`, 200 samples each; noise probe = float arrays N(0,1), bool arrays Bernoulli(0.5), 100 samples; zeros probe 3 samples):\n\n```\n%s\n```\n\n   Revisions of the fixed criterion: %s\n" % ("\n".join(pre[c]), REV.get(c, "0 (no change of the analysis after the first version).")))
    txt.append("6. **Timing** (fixed, mean of 30 calls on plus samples): t = %s s, g = %s s, S = %s (2 worlds + 1 control + 0 premises + 0 relational pairs + 2 probes); estimate 2 x 200 x (S+1) x (t+g) = %s s (limit 900 s).\n" % (t, g, S, est))
    txt.append("7. **Deviations from the private note, problems, skeleton requests:** %s Skeleton requests: none.\n" % DEV[c])
    txt.append("Faulty criterion: never run or simulated; only an `ast.parse` syntax check and a static name analysis (`symtable`, no execution) were done on it. Truth_Gate was not run.\n")
    open(os.path.join(CASES, c, "CASE.md"), "w", encoding="utf-8", newline="\n").write("\n".join(txt))
    print("CASE.md", c)
